INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррароти муҳимии оғози наботон дар паҳлӯи нухӯдкунӣ</h2><p>Нухӯд яке аз набототи маҳаллӣ-стратегӣ аст, ки барои фарҳоди баланд ва саҳми муҳим дар нигоҳ доштани экосистемаи бодҳаво тавассути таҳким кардани нитроген дар хок, нақши зарурӣ дорад. Бо маҳдудиятҳои захираҳои об дар аксари қисматҳои хушк ва нимхушк, гузашт аз усулҳои анъанавии обёрӣ ба тизикҳои дақиқ чун <strong>обёрӣ бо даракҳо</strong> ва <strong>обёрӣ бо намунаҳои пайваста</strong> на танҳо як интихоб, балки зарурати иқтисодӣ ва муҳити зист мебошад. Истифодаи дурусти ин технологияҳо метавонад сарфаи то 30 фоизро дар обҳои истифодашуда дар овардад ва ҳангоми зиёд кардани баробарнокӣ дар намнокии хок, боиси зиёд шудани вазни гӯбаргҳо ва сифати меҳоварии натиҷавӣ гардад.</p><h3>Фарҳаводҳои асосии нухӯдкунӣ бо тизикҳои даракӣ</h3><ul><li>Расидани об ба решаҳои равонакзанон, ки дар хок чуқурӣ кам доранд.</li><li>Кам шудани тамоми мустақими об бо шаклаҳои гулдорӣ ва кам шудани паҳншавии бемориҳои қарағизи баргҳо.</li><li>Имконияти ғизо диҳии ҳамзамони ноҳия тавассути маҳлули ғизоӣ (фитигатион), ки барои давраи офтобӣ хеле муҳим аст.</li><li>Корбардории дақиқтари ғалавҳои зараранок нисбат ба ибридҳии паҳшиданиҳо бо сабаби хомешавии сатҳи байни лӯлаҳо.</li></ul><p>Барои комёби дар ин система, дониши амиқ дар бораи ниёзҳои обии ноҳия дар ҳар давраи офтобӣ муҳим аст. Агар хоҳед бо нишондиҳандаҳои фаннӣ ва нишондиҳандаҳои дақиқтар барои арзёбии системаҳои обирӣ шинос шавед, метавонед ба мавзӯи ҳосилнокии菠菜 дар гектар нигарӣ доред, ки гарчанде меҳви дигар аст, вале принсипҳои калибрасияи системаҳои қатрагӣ барои ноҳияҳои бо вазни паст (аз ҷумла афтобӣ) хеле монанд аст.</p><p></p><h2>Усулҳои кишту кору тарҳрезии фанни системаи обирӣ</h2><p>Киштуkori афтобӣ бо системаи қатрагӣ ниёз ба ҳамёфии дақиқ байни сатҳи токҳо (бакичканак) ва сатҳи лӯлаҳои обирӣ дорад. Усули маъмултарин, киштуkori дар силсилаҳои мувозияткунанда аст, ки лӯлаҳои қатрагӣ равоқ аз сатҳи токҳо ё дар масофаи муайян аз он (масалан, 10 то 15 см) ҷойгир мешаванд. Ин тартиб кафолат медиҳад, ки решаҳои асосӣ, ки дар чуқурӣ то 20-25 см мерасанд, пурра дар минтакаи таркунӣ (Wetted Zone) бошанд.</p><h3>Интихоби намуди лӯла ва масофаи байни қатрасазҳо</h3><p>Барои нӯг, аз сабаби нисбатан заиф будани системаи решаҳо нисбат ба гиёҳҳои кулӯлаи чуқур, истифодаи лаблабрҳои қатқатпаз бо фосилаи қатқатпаз 20 ё 30 сантиметр тавсия дода мешавад. Фосилаи 20 сантиметрӣ пӯшиши беҳтар ва якхатарро ба вуҷуд меорад, вале хараҷи баландтар дорад. Фосилаи 30 сантиметрӣ барои хокҳои сабуктар бо заробии тез мувофиқ аст, ҳоле ки дар хокҳои равгон, фосилаи 20 сантиметрӣ беҳтар аст, то хомашавии байни қатқатпазҳо пешгирӣ шавад. Интихоби намуди лаблабр ба сифати навор ва тип низ робитаи мустақим дорад; як роҳнамои муфид барои ин интихоб, омӯзиши мақолаи чӣ тавр навори абории қатқатпазии мувофиқро интихоб кунед, ки ба устувории фишор ва умри муфиди лаблабр низ ишора мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-نخود-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت نخود با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кӯтобаҳкӣ обёрӣ бо усули қатқатпаз нақшаи обёрӣ нӯг</figcaption></figure><table><thead><tr><th>Намуди хок</th><th>Фосилаи тавсияшудаи қатқатпаз</th><th>Суръати ҷараёни ҳар як қатқатпаз (литр/соат)</th><th>Шумораи қатқатпазҳо дар ҳар як метри лаблабр</th></tr></thead><tbody><tr><td>Сабуки (шолӣ)</td><td>20 сантиметр</td><td>2 то 3</td><td>5</td></tr><tr><td>Лозам (Loham)</td><td>30 сантиметр</td><td>2</td><td>3.3</td></tr><tr><td>Оғир (гилӣ)</td><td>20 сантиметр</td><td>2</td><td>5</td></tr></tbody></table><p>Навари тиб ҳамчун ягон мулоими иқтисодӣ барои системаҳои қатравӣ, хати бордор аст, ки обро бо намҳои нозук дар болои хок ё зангиҳо мемонад. Ин усул барои нутҳо дар шароити хокҳои сабук ва кӯҳистонӣ, ки нархи системаи қатравӣ бо филтератсияи дақиқ хеле баланд аст, маъмул аст. Аммо, навари тиб ба эҳтиётони зиёдтар дар баланднокӣ лозим аст, то аз ҷамъшавии об дар як нуқта ва гург мондани қисми дигар пешгирӣ шавад. Барои фаҳмиши беҳтари методологияҳои одави навари тиб, хондани асосҳои одави навари тиб таъриф мекунад.</p><p></p><h2>Барномаи тақвиру (Irrigation Schedule)</h2><p>Муҳимтарин душворӣ дар одави қатравии нутҳо, мувофиқсозӣ бо фазаҳои ҳассоси растаки ҳаст. Нут як растаки яксола аст, ки марҳилаи тезии афзоиш ва ҳассосии стресси обӣ дар марҳилаи шабагӣ ва нутдориеро дорад. Аз рӯи таҳқиқоти агрономӣ, барномаи умумии одавӣ чунин аст:</p><ol><li><strong>Фазаи обӣ (то ҳамаи шабагаҳо шавад):</strong> Дар ин марҳила, растаки ба оби кам ниёз дорад. Одавӣ бояд сабук ва такрорӣ бошад, то аз дарозии зиёди асаки ва баландонашавӣ пешгирӣ шавад. Ба ҳисобни ҳадди акс 4 то 6 соат одавӣ дар ҳафта.</li><li><strong>Фазаи шабагӣ ва ташаккули нутҳо (марҳилаи ҳассостарин):</strong> Ин давра ҳосилноктарин марҳила дар баробари камшавии об аст. Хушкӣ ҳатто барои 24 соат метавонад гулҳоро пароканда кунад ва боиси камшавии диққатнокони дана гардад. Дар ин ҳафтаҳо, ҳаҷми обориш бояд ба ҳадди аксар расад. Рутубати хок бояд дар ҳудуди қобилияти нигоҳдории решаҳо нигоҳ дошта шавад.</li><li><strong>Фазои данагирӣ ва расидан ба пухтар:</strong> Бо расидан ба пухтарии физиологӣ, ниёзи обии растани ба татбиқ кам мешавад. Оборишҳоро тадриҷан кам кунед, то растани дар ҳолати нимхушк қарор гирад ва аз пухтан дاناҳоро пешгирӣ шавад.</li></ol><p>Барои ҳисобкунии дақиқи ҳаҷми обориш, шиносӣ <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%DA%AF%D9%88%D8%AC%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">молдаи барзиқи бодриро дар гектар</a> ҳамчун тағйирёбандаи зичии решаҳо метавонад дар сохтани моделҳои риёзии истеъмоли об кӯмакрасон бошад, гарчанде ки барои бодри одатан зичии бад (250 то 350 килограмм дар гектар) собит аст ва диққат бар идоракунии рутубати хок аст.</p><h3>Идоракунии рутубати хок бо сенсорҳо</h3><p>Ба ҷои таваққуи комил ба соат, истифодаи сенсорҳои рутубати хок дар чуқурии 15 ва 30 сантиметр, даққати нақшаи оборишро то 50 дарсад зиёд мекунад. Андозаи обориш (оғози обориш) вақте аст, ки рутубати хок ба 40 дарсади қобилияти нигоҳдорӣ расад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-نخود-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت نخود با آبیاری قطره‌ای - تصویر 2"/><figcaption>Method of sowing, drip irrigation, schedule for crop, chickpea</figcaption></figure><p></p><h2>Practical tips and smart farm management</h2><p>The use of drip irrigation for chickpeas is incomplete without integration with full fertility management (Fertigation). Nutrient solutions must have an appropriate concentration to prevent precipitation in emitters. The pH of the nutrient solution must be maintained between 5.5 and 6.5. Also, a mismatch between the filtration system and water quality can cause emitters to clog, leading to uneven irrigation.</p><h3>Common challenges and solutions</h3><ul><li><strong>Emitter clogging:</strong> Use a disc filter with 120 mesh and repeat system flushing every 2 months.</li><li><strong>Other issues: Seed shattering:</strong> If seeds shatter early, there may be water stress during the sensitive phase; increase irrigation volume by 20 percent in the first 2 weeks of flowering.</li><li><strong>Бемориҳои заминашон:</strong> Омодории чуқуқпа сари нигоҳдории намии баланд дар решаҳо шароити мувофиқро барои вайроншавии решаҳо эҷод мекунад. Сикли 7 рӯзаи наҳориро риоя кунед, то муқовимати замин ба бемориҳо зиёд шавад.</li></ul><p>Барои муқоисаи самаранокии дигар наботот, ки аз системаи монанд истифода мебаранд, омӯзиши ҳосили ҷавдор ва дурсер дар як гектар мебошад, ки нигоҳи хуберо дар бораи таъсири омодории дақиқ ба дигар анбоҳунаботот ба шумо медиҳад ва меъёрҳои самаранокиро равшантар менамояд.</p><h2>Саволҳои мӯҳим (FAQ)</h2><h3>Оё навар туб лихоро барои гилбурӯн беҳтар аз чуқуқпа аст?</h3><p>Вобаста ба замин ва бадҷет. Навар туб лихоро арзонтар аст ва барои заминҳои чиндор бо шитоби мувофиқ метавонад истифода шавад, аммо чуқуқпа якхатӣро баландтар ва назорати беҳтарро аз бақия дорад. Барои сортҳои ҳисобҳои ва паловҳои ҳассоси гилбурӯн, чуқуқпа имконоти бехатаратр аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-نخود-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت نخود با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule гилбурӯн</figcaption></figure><h3>Ҳангозе омодориеро тоқим кунем?</h3><p>Оддаҳо тақрибан 10 то 14 рӯз пеш аз ҳосилкашӣ, обро пурра такон диҳед, то ки донҳо хушк шаванд ва фурӯрӯнии онҳо пас аз ҳосилкашӣ кам шавад.</p><h3>Оё дар обкории қатрагӣ зарурати иловаии хокзарӣ мавҷуд аст?</h3><p>Не. Обкории қатрагӣ ба сабаби бисории боқимондаҳо ҳассосияти ҷузъӣ ба хокзарӣ дорад. Ҳатто дар баъзе ҳолатҳо, бисории боқимондаҳо метавонад боиси фишори физиологӣ гардад. Идоракунии дақиқи решаҳо муҳимтар аз идоракунии хокзарӣ аст.</p><h2>Хулоса</h2><p>Корбасории нахуд бо обкории қатрагӣ ё банди тип, омехтае аз дониши агронимикӣ, техникавӣ ва идоракунии манбаъҳо мебошад. Муваффақияти ниҳоӣ на танҳо ба намуди системаи насбшуда, балки ба иҷрои дақиқи нақшаи тақсимоти вақт, назорати мубрами намҳои хок ва якпорчагии фортисиат вобаста аст. Бо риояи принсипҳои дар ин дастур зикршуда, шумо метавонед ҳангоми кам шудани арзиши об ва кӯда, самаранокии маҳсулот ва сифати онро дар сатҳи баланд нигоҳ доред. Ошноӣ бо принсипҳои шартҳои асосӣ бо таҳқиқи Сулеймонӣ ва принсипҳои муҳандисии обкорӣ, асоси устувор барои ҳар як корбасории дақиқ мебошад. Сармоягузорӣ ба дониши техникавӣ, кафилати самаранокии аст.</p>\n<p><strong>Мавзӯи алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%A7%D8%B3%D9%81%D9%86%D8%A7%D8%AC-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8A7D8B3D981D986D8A7D8AC D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/lettuce-yield-per-hectare-factors-increase/">lettuce yield per hectare factors increase</a>, <a href="https://navar-abyari.ir/piyozcha-hosili-gektar-rohnomo/">piyozcha hosili gektar rohnomo</a></p>','Пуррашудаи дастури ғӯришт ва обёрӣ бо қутраҳо','Баланд бароракунии боварии модҳоти нуҳотро тавассути идоракунии дақиқи манбаъҳои об бо истифода аз системаҳои капкунӣ ва анбории бандӣ имконпазир аст. Ин мақола ба таҳлили муфассали техникӣ ва амалии парвариши нуҳот бо ин усулҳо ишора мекунад.','publish','closed','closed','pest-ravshanbar-obiari-qutara',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
