INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи кишткардани кӯпош ва аҳамияти дозати бодия</h2><p>Кӯпош яке аз сабзавоти хеле маъмул ва муфид дар бозорҳои маҳаллӣ ва содиротӣ аст, ки нақшабарии дақиқро аз марҳилаҳои ибтидоии кишт то ҷамъоварии ниҳоӣ талаб мекунад. муайян кардани <strong>Miqdori bodiya-yi kuposhi dar hektar</strong> факат адади собит нест, балки омили тағйирёбандае аст, ки вобаста ба усули кишт (бо даст ё бо мошин), намуди бодия (баста ё бодияи тоза) ва шароити иқлимии минтақа таъйр мекунад. Бисёр деҳқонони навкорон дар ҳисоб кардани дозати бодия хатоҳои маъмулӣ менамоянд, ки боиси рақобати шадид байни растанӣҳо ва паст шудани сифати ниҳоии маҳсул мегардад. Дар идома, мо ин параметрҳоро бо тафассул таҳқиқ мекунем, то шумо танҳо метавонед беҳтарин қарорро барои кишти худ қабул кунед.</p><p>Илова бар бодия, системаи обёрӣ нақши муайянкунанда дар барориши ниҳоӣ дорад. Истифодаи системаҳои муосир, чун <a href="https://navar-abyari.ir/types-irrigation-tapes-performance/">Намудҳои намоёнҳои обёрӣ ва кори онҳо</a> метавонад боиси кам шудани зарари об ва зиёд шудани якхелагии афзоиши растанӣҳо гардад. Интихоби дурусти намоёнҳои тиб ё чизе чизон, мустақиман бо миқдори истифодаи об ва сathi зери кишт вобаста аст.</p><h2>Меъёрҳои техникӣ барои ҳисоб кардани дозати бодияи кӯпош</h2><p>Барои ҳисобкунии дақиқи ниёз ба бубурӯрӣ (бӣҷи), аввал бояд мафҳуми зичии партобишро фаҳмем. Бӯҷӣ рӯяке аст, ки ба сабаби решаи амиқи худ ва рушди тез дар ду ҳафтаи аввал, ба фосилакунии мунтазам ниёз дорад. Дар усулҳои анъанавӣ, одатан бӣҷиро ҷавфидан (партобидан) мекунанд, аммо дар усулҳои муосир, истифодаи ҷиби партобиш (Rill) тавсия дода мешавад.</p><h3>Формулаи ҳисобкунии миқдори бӣҷӣ асосан ба фосилакунии байни наботот</h3><p>Агар мо хоҳем, ки фосилаи байни набототро 10 santimetr ва фосилаи байни сафҳоро 20 то 30 santimetr гузорем, ҳисобкуниҳо ин сурат мешавад. Ҳар гектар тақрибан 10,000 метри мураъб аст. Бо фарзияи фосилаи наботот 10 santimetr, дар ҳар метри дарозии хат 10 наботот хоҳем дошт. Дар як метри мураъб бо фосилаи сафҳ 20 santimetr, 5 саф ҷойгир мешавад. Пас, шумораи наботот дар ҳар метри мураъб 50 то мешавад. Барои як гектар, шумораи умумии набототҳо то 500,000 то расидан меояд. Бо назардошти сатҳи нақби 85 то 90 фоизии бӣҷҳои стандартӣ, миқдори ибтидоии бӣҷ бояд каме зиёда аз 500,000 то бӣҷ бошад. Бо вазни тақрибан 1000 дони бӣҷи бӯҷӣ тақрибан 8 то 10 грамм, ба миқдори 4 то 5 килограмм бӣҷи холис дар гектар расидан мумкин аст. Ин рақам вобаста ба андозаи донҳо (хурд, миёна, калон) иваз мешавад.</p><h2>Нуқтаҳои амалии партобиш ва идоракунии фазои байни сафҳо</h2><p>Пас аз ҳисобкунии миқдори бӣҷ, усули тайёр кардани зери партобиш хеле муҳим аст. Хурак бояд пурра қаддакӯфта (коруда) ва аз кӯлохҳои бузург озод бошад, то бӣҷҳо дар чуқурии якхела партобида шаванд. Ин якхелаӣ саббот мекунад, ки дар марҳилаи оянда идоракунии обгирӣ содатар мешавад. Барои кишовароне, ки аз риши обгирӣ истифода мебаранд, ҳамсафу будани сафҳои партобиш бо хатҳои обгирӣ зарур аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-جعفری-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر جعفری در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop бӯҷӣ</figcaption></figure><p>Ҳангоми корезӣ, диққат кунед, ки бобҳои петрушка хеле хурданд ва баъзан барои зиёд кардани дақиқӣ бо регаи сабз ё перманганати потассиум омехта карда мешаванд, то бубард, ки бобҳо бештар дида шавад. Ин кор махсусан дар системаҳои корезии механиқӣ, ки ихтиёри танзими дақиқи миқдорро надоранд, хеле бокӯҳ аст. Инчунин, истифодаи ҳосили дар гектар ҳамчун меъёри баррасии potentials корезӣ метавонад ба шумо кӯмак карда, ки миқдори бобро мувофиқи ҳадафи охирин танзим кунод. Агар ҳадафи шумо истеҳсоли боб бошад, миқдори корезӣ бояд камтар бошад, то ки равишҳо энергияи кофӣ барои шаклгирӣ гул ва мева дошта бошанд.</p><><h2>Таъсири системаҳои обёрӣ нафаскашӣ ва нории тийб ба зиёдӣ корезӣ</h2><p>Як аз хатоҳои оддӣ дар корезии сабзиёта, ҷудо дидан марҳилаи парашуи бобҳо ва марҳилаи обёрӣ аст. Дар воқеъ, навъи системаи обёрӣ муайян мекунад, ки шумо чӣ қадар метавонед зиёдиро бардашҳо зиёд кунед. Дар системаи обёрии баронӣ, маҳдудияте дар зиёдӣ корезӣ вуҷуд надорад, аммо дар системаҳои нафаскашӣ ва нории тийб, миқдори баромади ҳар нафаскашӣ ё шланги тийб параметри собит аст. Агар зиёдиро бардашҳо аз фосилаи байни нафаскашҳо беш фарқ кунед, равишҳо дар як минтақаи муайян бо якдигар бемуборати задуран барои ҷабби об ва моддаҳои ғизоӣ доранд.</p><h3>Оптимизатсияи фосилаи бардашҳо бо нории тийб</h3><p>Лентиҳои рех (Drip Tape) ба сабаби фарогирии беҳтари сатҳ, нисбат ба қатқаҳоҷиҳо ҷудасохтор, имконияти татбиқи зичии баландтарро фароҳам меоранд. Дар лентиҳои рех, об бо шакли идомадор дар тӯли хат паҳн мешавад. Бинобар ин, шумо метавонед нӯрҳоро бо масофаи 5 то 7 сантиметр ҷоҳандӣ кунед, бо шароитаки таҳвути лентия рех аз ҳадди ақали талаботи умумии растанӣ дар он масофа гузарад. Барои мисол, агар аз миқдори ғаллоби ғӯлоти сабз ҷои гектарро ҳамчун намунаи ҷониби ҷони ҷони ҷони ҷони Ҷонии кили кили кили кили</p><h2>Ҷадвали роҳнамоии меъёри боб ва масофаи ҷонибӣ</h2><p>Барои равшантар кардани масъала, ҷадвали поён хулосаи параметрҳои тавсияшуда барои ҳисоб кардани <strong>миқдори боби ҷониби ҷонибӣ</strong> аз рӯи усулҳои гуногунро нишон медиҳад. Ин рақамҳо миқдорҳои идеалӣ мебошанд ва бояд бо назардошти бомунафқати минтақаи худ соҳибкорӣ шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-جعفری-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر جعفری در هکتار: راهنمای جامع - تصویر 2"/><figcaption>seed rate per hectare crop ҷониби ҷонибӣ</figcaption></figure><table border="1" cellpadding="5"><tr><th>Усули ҷонибӣ</th><th>Масофаи байни нӯрҳо (см)</th><th>Фосилаи қаторҳо (см)</th><th>Ниҳоби анвои бӯда (кг/га)</th></tr><tr><td>Дасти кор (Партоб)</td><td>10-15</td><td>25-30</td><td>5-7</td></tr><tr><td>Механизатсияшуда (бо қотима)</td><td>10</td><td>20-25</td><td>3-5</td></tr><tr><td>Рилли (Rill)</td><td>5-10</td><td>15-20</td><td>2-4</td></tr></table><p>Нуқтаи муҳим дар ҷадвали боло ин аст, ки дар усули рилли, бо вуҷуди zichии баландтар, чунки бехи бодӣ дар каиширӣ ва бо миқдори мувофиқи об пешнамоӣ кишт шудааст, суръати нашӯи баландтар аст ва лозимият ба бехи иловагӣ камтар аст. Усулҳои механикӣ низ ба сабаби дақиқати баланди мошинҳо, камтарин аз ҳароми бехро доранд.</p><><h2>Нуқтаҳои калидӣ дар марҳилаи нашӯи ва паштӣ</h2><p>Пас аз ғалдон гузоштан ва номи наботот расидан ба баландии 5 то 7 см, марҳаҷи ғалдонро (Thinning) оғоз мекунад. Дар ин марҳаҷа, набототи иловагӣ, ки сабаби ихтилошӣ мешаванд, ихроҷ ё бардошт мешаванд. Аз ғалдонҳои ростиш (типи) истифода баред, боварӣ ҳосил кунед, ки ғалдонҳо ё нурҳои ғалдонӣ ҳангоми амалиёт барои ҳаби ғалдонро (Thinning) заминананд. Нурҳои ғалдонии сифати паст метавонад дар натиҷаи тамос бо пичиш ё дастҳои кӯрокчӣ сӯрохи шаванд. Барои ин мақсад беҳтар аст, ки сарфаи нурҳои ғалдонӣ барои як гектарро дар назар гиред ва нурҳои сифати беҳтарро интихоб кунед, ки муқовимати механикии баландтар доранд, то даъмати хомӯшшавии мушкилоти дар доираи ҳаби намоёнро надоред. Ин масъала ба қитъаи бехи ибодӣ ба таври мустақим таъсир мерасонад; зеро таъмини солимии системаи ғалдонӣ, ба шумо имкон медиҳад, ки қитъаи бехро бодилкушӣ ва бе ҳар гуна ҳисор бодазанд.</p><h2>Ҷавоб ба саволҳои мунтазам (FAQ)</h2><h3>1. Оё миқдори бехи сабзӣ дар як гектар дар шароити гармуз бо минтақаҳои мухталиф фарқ мекунад?</h3><p>Бале. Дар гармузҳо, бо сабаби идоракунии муҳит, метавонед зичии ғалдонро баланд бардоред. Заминаи маҳдуди гармуз боиси истифода аз намоишкунӣ ва афзоиши амудии наботот мебошад, бинобар ин миқдори бех дар заминаи мушаххас метавонад то 20 фоиз баландтар аз ғалдони озод бошад, ба шароити тарозудодани мувофиқ.</p><h3>2. Дар кадом вақт беҳтар аст бехи сабзиро ғалдон гирям, то мушкилоти ғалдонӣ ҳал шаванд?</h3><p>Вақти беҳтарин барои ғалдон вобаста ба мавсим аст, аммо дар мавсимҳои нимнамнок, ғалдони моҳи тираммон одатан бартарӣ дорад. Агар дар фасли гарм ғалдон гиред, ҳатман аз торпаҳои соя истифода баред, то суръати намоёншии бех нигоҳ дошта шавад. Дар ин шартҳо, истифода аз системаҳои ғалдони ростиш бо обшавии паст ва такрори баланд ҳокият аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-جعفری-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر جعفری در هکتار: راهنمای جامع - تصویر 3"/><figcaption>миқдори бех бар як гектар зироати сабзӣ</figcaption></figure><h3>3. Оё дар нурҳои ғалдонӣ (типи), масоҳати байни буттаҳо метавонад камтар аз масоҳати байни ғалдонкунандаҳо бошад?</h3><p>Дар нӯри тиб, чун об ба таври пайваст паҳн мешавад, маҳдудияти сахке монанди чархакҳои ғайри алоҳида вуҷуд надорад. Аммо тавсия мешавад, ки фосилаи кӯбоҳ аз фосилае, ки дар он нохия хок хушк мемонад, камтар набошад. Дар хокҳои шина, фосилаи кӯбоҳ бояд каме бештар бошад, то решаҳо барои ҷустуҷӯи намӣ дар амиқтарӣ кашида шаванд.</p><><h2>Хулоса ва тавсияҳои охирин</h2><p>Муайян кардан <strong>Миқдори булӯри дилбаста дар ҳектар</strong> Як раванди пӯшкарост аст, ки омезиши илми кишоварзӣ ва муҳандисии обёрӣро талаб мекунад. Ба ҷои боварӣ ба рақамҳои собит, ҳамеша аз формулаҳои зичии кӯбоҳ истифода баред ва онро бо намуди системаи обёрии худ (нӯри тиб ё чархакӣ) мутобиқ кунед. Истифодаи нӯрҳои бо сифат ва нақшакашии дақиқ барои марҳилаи кӯбоҳкушӣ, калиди дастӣ ба беҳтарин самаранокӣ аст. Ҳамеша таҷриба ва огоҳии худро дар боғи хурд, пеш аз пуркунии тамоми сатҳ, анҷом диҳед, то дозаҳои булӯр ва рафии обёриро беҳтар кунед. Бо риояи ин нуқтаҳо, шумо метавонед маҳсулот якнавоза, солим ва бо решаҳои амиқтарро ба даст оред, ки нархи ҳар килограммро дар бозор баланд мекунад.</p>\n<p><strong>Мавзӯи алоқаманд:</strong> <a href="https://navar-abyari.ir/components-drip-irrigation-tape-dripper/">components drip irrigation tape dripper</a>، <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%A9%D8%A7%D9%87%D9%88-%D9%BE%DB%8C%DA%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DAA9D8A7D987D988 D9BEDB8CDA86 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>، <a href="https://navar-abyari.ir/eggplant-seed-quantity-per-hectare-planting-irrigation-tips/">eggplant seed quantity per hectare planting irrigation tips</a></p>','Миқдори барди кӯбудун (ҷаҷарӣ) дар як гектар: Раҳнамои пурраи парвариш ва обёрии беҳтар','Ҳисобкунии дақиқи миқдори тохи карандил дар ҷамъият яке аз марҳилаҳои муҳимтарин дар кишоварӣ аст. Дар ин дастурамали муфассал, шумо формулаҳои зичии кӯмаккунӣ, масофагузории мувофиқ ва усулҳои обгирӣ-қаппӣеро меомӯзед, ки суръати афзоишро беҳтар мекунанд.','publish','closed','closed','miq-dori-barzi-kobudun-da-yek-gektor',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
