INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كمية بذور الخس المطلوبة للهادار مع دليل شامل عن زراعة الخس والري الدقيق في العراق. احسب البذور بدقة لزيادة المحصول وخفض التكلفة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
