INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти дақиқии миқдори токи каду барои ҳокта</h2><p>Каду яке аз сабзавотҳои тезрасидан буда, дар бозорҳои Ирон ҷойгои хос дорад. Муайян кардани <strong>миқдори токи каду барои ҳокта</strong> на танҳо як рақами сода аст, балки мустақиман ба хароҷоти истеҳсол, зичии ниҳоии растаниҳо ва дар натиҷа, сифат ва вазни ҳар як сарраҳи каду таъсир мерасонад. Кишоврон ва боғдороне, ки аз усулҳои муосири оборӣ монанди қатрагӣ (қатраӣ) ё системаи чизи (ниҳорӣ) истифода мебаранд, ба мувофиқати дақиқ байни зичии ниҳол ва системаи оборӣ ниёз доранд. Ин дасторон шуморо кӯмак мекунад, ки бо фаҳмидани тағйирёбандаҳои гуногун, миқдори мувофиқи токро барои замини худ ҳисоб кунед ва аз талафоти захираҳо пешгирӣ намоед.</p><p>Истифодаи намунаи мувофиқи ниҳол бо <a href=\'https://navar-abyari.ir/zira-sabz-tukhm-miqdor-gaektar-kisht-parastori/\'>Дастурбарии ниҳол кардани сабзавот ва миқдори ток дар ҳокта</a> метавонад ба шумо нишондиҳандаи пурраи бештар диҳад.</p><h2>Омилҳои таъсиррасон ба муайян кардани миқдори токи каду</h2><p>Миқдори бодири латук барои як гектар замин ба омили бисёр вобаста аст. Фаҳмидани ин омилҳо барои ҷонибидани ғанин зарур аст. Муҳимтарин омили ин интихоби навъи бодир (ҷавонадҳӣ) ва нисбу латук мебошад, ки ҳар яке амали бӯстони гуногун доранд.</p><h3>Таъсири шароити иқлимӣ ва бодир</h3><p>Дар минтақаҳои харошӣ, одатан зичии ҷонибидан каме бештар аз минтақаҳои гармшанос аст, то аз яхбаст ва рақобат бо одави ғайрикор пешгирӣ шавад. Ғайр аз ин, агар шумо аз бодири нисбу хибридии решаи қавӣ истифода баред, метавонед масофаҳои беҳтарро ба назар гиред. Дар умум, <strong>Миқдори бодири латук дар гектар</strong> Одатан байни 20 то 40 килограмм дар гектар тағйир мекунад, аммо ин фосила хеле васеъ аст ва бояд вобаста ба шароити маҳаллӣ танзим карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاهو-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر کاهو در هکتار: راهنمای جامع - تصویر 1"/><figcaption>seed rate per hectare crop латук</figcaption></figure><h3>Усули ҷонибидан: мустақим ё бозоргӣ</h3><p>Яке аз муҳимтарин тағйирёбандаҳо усули ҷонибидан аст. Дар ҷонибидани бодири мустақим, бо сабаби зояҳо аз сатҳи ғайридузбаста ва шароити номаълуми ҷавонадҳӣ, бояд миқдори иловагии бодирро ба назар гиред. Аммо дар усули бозоргӣ, чун шумо танҳо бозоргиҳои солимро дар заминаи асосӣ ҷонибидед, миқдори аввали бодир барои ғӯр (Nursery) муайян аст ва дар ҷои асосӣ ба ҳисобкунии дубора ҳоҷат нест. [Пайванди пешниҳодшуда: <a href=\'https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D9%86%D8%AE%D9%88%D8%AF-%D8%AF%DB%8C%D9%85-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/\'>Шуми бӯди навдаи баҳорӣ дар гектар</a> [Барои муқоиса бо дигар маҳсулоти кишоварзӣ]</p><h2>Ҳисоби дақиқи зичӣ ва масофагӯйӣ</h2><p>Барои дарёфтан <strong>Шуми бӯди сабзӣ (ладука) дар гектар</strong>, аввал бояд масофагӯйии дурустро муайян кунед. Одатан барои сабзӣ (ладука), масофа байни сатҳҳо аз 45 то 50 сантиметр ва масофа байни ноҷурҳо дар сатҳ аз 25 то 35 сантиметр тавсия дода мешавад. Ин рақамҳо вобаста ба намуди интихобшуда (россии, фаронсуӣ ва ғайра) метавонанд тағйир ёбанд.</p><h3>Ҷадвали роҳнамои масофагӯйӣ ва шуми ноҷурҳо дар гектар</h3><table><tr><th>Намуди сабзӣ (ладука)</th><th>Фосилаи раф (см)</th><th>Фосилаи бутта (см)</th><th>Шумораи нӯра дар гектар</th><th>Суръати намудан (%)</th></tr><tr><td>Копаст рафшакӣ (кишмish)</td><td>40-45</td><td>20-25</td><td>90,000 - 110,000</td><td>60-70</td></tr><tr><td>Калабурка</td><td>45-50</td><td>25-30</td><td>70 000 - 90 000</td><td>65-75</td></tr><tr><td>Калабуркаи сабз/франсусӣ</td><td>50</td><td>30-35</td><td>60,000 - 80,000</td><td>70-80</td></tr></table><p>Бо донистани шумораи ниҳоии тобҳои мардуми ва суръати намоиш додани бӯяда, имкон аст вазни зарурии бӯядаро ҳисоб кард. Истифода кунед, ки ин ҳисобҳо барои ғайсбистани мустақим мебошанд ва дар усули ғайсбистани чангҳо, бӯяди зарурӣ танҳо барои сатҳи ғайсбистанӣ (ки хеле хурдтар аст) лозим аст.</p><h2>Нақши ороғи доирагӣ ва нахушӣ дар идоракунии зичӣ</h2><p>Яке аз имтиҳонҳои асосӣ дар ғайсбистани гӯштӣ бо зичии баланд, идоракунии рутубати хок аст. Истифодаи системҳои ороғи нахушӣ ё <a href=\'https://navar-abyari.ir/%d8%a7%d8%ac%d8%b2%d8%a7%d8%a1-%d8%b3%db%8c%d8%b3%d8%aa%d9%85-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d9%82%d8%b7%d8%b1%d9%87%d8%a7%db%8c-%d8%a8%d8%a7-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c/\'>Қисмҳои системаи ороғи нахушӣ бо доирагӣ</a> метавонад ба нигоҳ доштани рутубати якхела дар решаи рӯягӣ кӯмак расонад. Вақте <strong>Миқдори бардошти каду дар як гектар</strong> Аз бобати зиёд будан, решаҳо рақобати бештарро барои ҳосил кардани об ва моддаҳои ғизоӣ доранд. Дар ин ҳолат, тақсими яксон ва баробари об тавассути системаи чистани ғази (drip tape) барои кафолат додани ҳамвории андозаи сари каду (Head size uniformity) муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاهو-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر کاهو در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Нисбат барои ғаллокадаҳои каду дар як гектар</figcaption></figure><h3>Таъсири фишор ва суръати чистани чистани ғази (drip tape) ба устувории ҳосил</h3><p>Агар аз чистани чистани ғази (drip tape) истифода баред, бояд маъмул бошед, ки фосилаи миёни чистакунҳои об (Emitter Spacing) бо фосилаи дарҳамгирӣ бо растанӣ ҳамроҳ аст. Ин мувофиқат ба он сабаб мегардад, ки об рост дар минтақаи решаҳои асосии каду бошад ва аз хабаргирӣ (тақсими нокофӣ) дар заминаи халос миёнаи сатҳҳо хобор намешавад. Барои маълумоти бештар дар бораи насби дуруст, ба <a href=\'https://navar-abyari.ir/qadamhoi-nasbi-navori-tip/\'>Гузарҳои насби чистани чистани ғази (drip tape)</a> муроҷиат кунед. Инчунин, агар барои маҳсулотҳои дигаратон мисли ғунҷум дар ҷустуҷӯи роҳҳои ҳал мисли ҳаҷми чистани чистани ғази (drip tape) барои як гектар бошед, шумо метавонед муқоиса бо каду дошта бошед.</p><h2>Маҳалҳои амалиётӣ барои беҳтаркунии дарҳамгирӣ бо каду</h2><ul><li><strong>Тайёр кардани рӯҳи баромаднокӣ:</strong> Хакки рӯҳи баромаднокии хасиш бояд нарм, бе сангҳо ва бой бо моддаҳои органикӣ бошад. Тақрибан 1% санги иловагӣ метавонад боиси нобудшавии хасиши ҳаттӣ гардад.</li><li><strong>Дараҷаи кӯтазонӣ:</strong> Хасиш дони бисёр майдор дорад. Дараҷаи кӯтазонӣ бояд хеле кам бошад (тақрибан 5 то 10 мм). Барои истифода барои кӯмак ба рушд, метавонед барои нигоҳ доштани намнокӣ аз қабати нозуки чӯпон ё бобист истифода баред.</li><li><strong>Идоракунии одаҳо:</strong> Азбаски рушди хасиш нисбатан дер аст ва фазои байни бугдонҳо кушод аст, одаҳо душмони асосии кам шудани зичӣ мебошанд. Истифодаи муносиби воситаҳои химиявӣ барои кушодани одаҳо дар марҳилаи пеш аз баромадан, калиди нигоҳ доштани шумораи охирини пайҳо аст.</li><li><strong>Алоҳи кардани пайҳои иловагӣ (Тхиннинг):</strong> Агар бо кӯтазонии мустақим <strong>М�о миқдори бӯи салат дар гектар</strong> ро баланд кунед, то зарари ғарадро пур карда, пас аз барғам шудан, ҷавонокиҳои заифро ҷудо кунед, то ҷавонокиҳои асосӣ ғайрат кифоя барои расидан пайдо кунанд. Ин кор боис мешавад, ки дарахти салати баргдор (кочан) калонтар шавад.</li></ul><h3>Таъсири рӯшноӣ ва соя дар парвариши зич</h3><p>Дар парвариши зич, сояи набототҳо бар якдигар яке аз омилҳои физиологӣ аст, ки бояд ба назар гирифта шавад. Агар зичӣ аз дараҷаи тавсияшуда зиёд бошад, набототҳо дар рӯшноии кам дароз ва нозук (Elongation) мешаванд ва дарахти салати баргдор (кочан) хурдтар ва сахттар истеҳсол мекунанд. Бинобар ин, риояи фосилаҳои стандарти бо истифода аз <a href=\'https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B4%DB%8C%D8%B1%DB%8C%D9%86-%D8%A8%DB%8C%D8%A7%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/\'>Мувҷи ҷамъоварии ширинъоб дар гектар</a> ё дигар маҳсулоти сабзавот метавонад намунае бошад барои муқоиса.</p><h2>Саволҳои маъмул оид ба парвариши салат</h2><h3>Оё метавон миқдори бӯи салатро барои парвариш дархонаи гарм иваз кард?</h3><p>Бале, дар хонакӯрӯза назорати муҳити мавҷуд аст. Одатан, зичии хонакӯрӯза метавонад каме камтар бошад, то ки ҷойи бештар барои рушди думолаҳои калонтар (Market Size) фароҳам оҳад. Дар ин ҳолат, <strong>миқдори бехи сабзи каллабаро дар гектар</strong> баробар (бо фарзияи табдили метри мураббаъ ба гектар) аз кӯрпайии озод камтар хоҳад буд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کاهو-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر کاهو در هکتار: راهنمای جامع - تصویر 3"/><figcaption>norma bazi bar hektar ziraat кали баро (seed rate per hectare crop каллабаро)</figcaption></figure><h3>фарқи бехи каллабаро бо сабзиҳои дигар, монанди ҷав, чист?</h3><p>каллабаро аз нигоҳи андозаи дунб (дано) хеле хурдтар аст ва ҳассосияти бештарро ба чуқурии кӯрпайӣ дорад. Барои муқоиса бо растаниҳое, ки дунб (дано)-ҳои калонтар доранд, метавонед ба дастури миқдори бехи бут (тобел) дар гектар (агар сарчашмаҳои алоқаманд мавҷуд бошанд) ё дастурҳои монанди он баргардед.</p><h3>оё системаи намои тӯл (нум) барои каллабаро мувофиқ аст?</h3><p>Бале, махсусан агар масофаи байни қаторҳо камтар аз 50 см бошад, намои тӯл (нум) беҳтарин вариант барои обёрӣи марказӣ (консенративӣ)-и решаҳо мебошад. Ин система имкон медиҳад, ки рутубат дар минтақаи решаҳо ҷамъ оҳад ва аз бемориҳои сабукӯбаки, ки аз хона кардани баргҳо ба вуҷуд меоянд, пешгирӣ кунад.</p><h2>Хулоса</h2><p>Муайян кардани дақиқ <strong>Миқдори тухми салоб (кахолъ) дар як гектар</strong> ин калиди муваффақият дар истеҳсоли салоби сифатнок аст. Ин миқдор собит нест ва ба навъ, усули кундан, шароити хок ва системаи обёркунии шумо вобаста аст. Бо истифода аз ҷадвалҳое, ки пешниҳод шудаанд ва бо назардошти сатҳи тарршид, шумо метавонед буҷети тухми худро беҳтар созед. Фаромӯш накунед, ки мувофиқат байни зичии коркунӣ ва сари обборкунӣ дар риштаҳои капель ё дрипер кафолати рушди якнавохт ва зиёд шудани ҳосили ниҳоии шумост. Сармоягузорӣ дар системаи обборкуни дақиқ мисли <a href=\'https://navar-abyari.ir/buls-akhdar-mawsout-haqtara/\'>бесат ақдара машҳур ҳектары</a> (манбае, ки ба системаҳои обборкунӣ алоқаманд аст) ва риояи принсипҳои ҷориниҳо роҳи шуморо ба ҷоринии серҳосил мебарорад. Ҳамеша эҳтиёт бошед, ки зичии зиёд боиси рақобати решаҳо ва кам шудани сифати думаллаҳо мегардад; пас дар кунан, ҳамеша эҳтиёткорона ва бо ғайбидории каме фазо амал кунед.</p>','Миқдори бӯғдони каду дар гектар: Раҳнамои мукаммали шӯрва ва обкунӣи дақиқ','Дар ин мақолаи ҷамъовар, ба таҳлили дақиқи миқдори боби салоти калантар ҳатари. Аз таъсири навъи замин ва шартҳои иқлимӣ то сарф ва кардани боб, то нуқтаҳои калидӣ дар лӯлакушӣ ва обирии нур тиби, ҳама чизро бидонед то маводи соғат ва камтарин осеби дошта бошед.','publish','closed','closed','seed-quantity-lettuce-hectar-tajik-farming-guide',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
