INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','شامل إدارة الري في الزراعة الحديثة' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل شامل لإدارة الري في الزراعة الحديثة يربط بين المبادئ الأساسية والتقنيات الذكية، مع التركيز على تحسين الكفاءة المائية لأغراض AFP والعمليتين التقنية والزراعية. دليلك العملي نحو ريّ دقيق وموفر للموارد.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
