INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Аҳамияти идоракунии дақиқи тасмаи дарии (дъирип тейп) дар парҳезории порей</h2>\n<p>Порей (Allium porrum) гиёҳест, ки решаҳои он хеле фазован буда, ҳисобнокии баланд доранд. Баръакси бисёр маҳсулоти дигар, порей барои ҳосили баланди диму (Gadam) ва баргҳои сабзи торик ба тармои комил ва муносиб ниёз дорад. Камбудии об ҳатто барои муддати кӯтоҳ метавонад ба назукии диму ва камшавии қобилияти бозарёфтии маҳсул оварда расонад. Аз тарафи дигар, зиёдшавии об боиси зарби фурурӯнии об ва камшавии умри ҳосил дар бозор мегардад. Дар ин ҷо, системаи оборӣи дӻрибиҳо, хусусан тасмаи дарии (дъирип тейп), нақши устухони идоракунии захираворо дар ин парҳезорӣ мевад. Вале танҳо насби тасмаи дарӣ кифоя нест; <strong>Нигоҳубини тасмаи дарии порей</strong> ва назорати давомноки он омили асосии самаранокии иқтисодии деҳқонӣ мебошад.</p>\n<p>Яке аз мушкилоти асосӣ дар нигоҳубини ин система, ҳайъати баланди порей ба кашиши моддаҳои ғизоӣ тавассути реша мебошад, ки дар сурати камшавии фишор ё тупшавии дӻрибҳо, сабзиши якхела дар тамоми ҳиссаи заминро тоб меорад. Барои фаҳми беҳтари робита байни андозаҳои гуногуни тасмаи дарӣ ва миқдори лозими об, шумо метавонед ба дастурубии ҳамаи чизҳо дар бораи фоидаҳои тасмаи дарӣ муроҷиат кунед, ки ба тафсилоти техникии санҷиши ҷарро муроҷиъат мекунад.</p>\n\n<h3>Татбиқи парҳезораки зич нақш дорад бар системии обӣ</h3>\n<p>Бӯи порей одатан бо зичии мушаххас дар ҳар гектар кӯшида мешавад. Дониши дақиқи зичии бӯӣ ба шумо дар мувофиқат додани суръати баромади дӻрибҳо бо шумораи кӯҳҳои фаъол кӯмак мекунад. Дастурубии <a href="https://navar-abyari.ir/leek-seed-per-hectare-iraq/">Миқдори бӯи порей дар гектар</a> Ин метавонад нуқтаи оғози ҳисобҳои ҳақиқии буҷаи обдорӣ шумо бошад. Агар зичии нигоҳдорӣ баланд бошад, фосилаҳо байни қатқотҳо бояд кӯтоҳтар ва суръати баромад камтар бошад, то ки аз гароми атрофи решаҳо пешгири шавад.</p>\n\n<>\n\n<h2>Фасли аввал: Насби дуруст ва назорати ибтидоӣ</h2>\n<p>Дарморди намуни тибби чархӣ аз лаҳзае оғоз меёбад, ки шумо намуниро дар замин пахмед. Баъзе кишоварон боварӣ доранд, ки дармордҳо маҳз шустани филтрро дар нимаи фасл ифода мекунад, аммо таҷрибаҳои майдонӣ нишон медиҳанд, ки 50% мушкилоти фаннӣ аз хатогиҳо дар марҳалаи насб ва интихоби системаи мувофиқ ба вуҷуд меоянд.</p>\n\n<h3>Интихоби қатқоти мувофиқ барои шароити хок</h3>\n<p>Хокҳои гилӣ, ки дар минтаҳои зиёди кишоварии мусир дар Эрон маъмуланд, баҳамшавии паст доранд. Дар ин шартҳо, истифодаи намуни тибби чархӣ бо қатқоти чархзан ё қатқотҳои бо фосилаҳои наздиктар аз ташаккули зангари сатҳӣ пешгири мекунад. Аввалан, бояд аз интихоби намуни обгузарони мувофиқ барои шароити иқлимии худ боварӣ ҳосил кунед. Намуни тибби чархии бехобар, ки дар офтоби мустақим пӯса мекунад, ҳар гуна кор барои дармордҳоро бе маъно менамояд.</p>\n\n<h3>Роҳандозии система дар рӯзҳои аввал</h3>\n<p>Пас аз паҳ кардани намуни, ҳатманро системаро бо фишори кам роҳандозӣ кунед, то ки аз дағони ҷойҳои пайвасти тӯбҳо ба кранҳо боварӣ ҳосил кунед. Дағон дар рӯзҳои аввали кишоварӣ боиси ташаккули боллаву тӯбҳоинамҳои рутубат дар атрофи намуни мешавад, ки метавонад ба решаҳои ҷавон зарар расонад. Инчунин, боварӣ ҳосил кунед, ки намуни дар зери баландиҳои хок ҷойгиридааст, то аз таъсири мустақими офтоб муҳофат шавад. Ин кор умри намуниро ду то се маротиба зиёд мекунад ва ниёз ба иваз карданро дар нимаи фаслро хомӯш мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-موسیر-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری موسیر با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care мусир</figcaption></figure>\n\n<h2>Фасли дуюм: Муоҳимоти рӯзона ва ҳафтаина</h2>\n<p>Moseer як растаи истеъмоли зиёди нитроген ва об аст. Бинобар ин, системаи оҳии шумо бояд қобилияти тақвиятдиҳии коэффисиентӣ (Fertigation)-ро дошта бошад. Нигоҳубини мунтазам маънои пайдогирии давомии саломатии филтраҳо ва ширҳои танзими фишорро дорад.</p>\n\n<h3>Партознии об: Қаламои хатогӣ яд накарда мешавад</h3>\n<p>Муҳимтарин қадам дар нигоҳубини линияи дриплери пастор, тозагии системаи партозкунӣ аст. Капулеҳои линияи дриплери пастор одатан дорои қадди хеле майдагӣ мебошанд, ки зарраҳои хурдтар аз 100 микрони блоку мекарданд. Мувофиқи ҳатанро истифода кунед ё филтри бурсӣ ва ҳар ҳафта (ё дар ҳолати обҳои пасткор, ҳар рӯз) онҳоро тоза кунед. Гузаштаги филтр ба паст шудани фишор оварда мерасонад ва капуреҳо дигар дуруст намешаванд, натиҷа нисфи ҳиссаи хушк ва нисфи дигари обшавӣ мешавад, ки душмони рақами якуни самаранокии маҳсул аст.</p>\n\n<h3>Контроли ҳарорати об ва кимиёвӣ</h3>\n<p>Агар аз оҳии тақвиятишуда истифода кунед, ҳатман аз шисеҳи нейтралатсия (Neutralization Chamber) истифода баред. Иловаи кальсий ва магний, ки дар натиҷаи баланд шудани pH ба вуҷуд меоянд, роҳи зудтарин барои хориҷ шудани дохилияи линияи дриплери пастор мебошанд. як тести сода: ҳар ду ҳафта, чанд капурро кушоед ва бо лумбарстексуксйон ё асанс бо нур ба дохили онҳо нигаред. ҳар гуна иловаи сафед ё зарғаки сабз нишонаи оғози гузаштаги аст. дар ин ҳолат бояд барномаи шустани кислотагӣ (сулфатронӣ ё ситрикӣ)-ро ба ҷадвали нигоҳубини худ илова кунед.</p>\n\n<>\n\n<h2>Фасли сеюм: идоракунии гузаштаги ва ислоҳот</h2>\n<p>Ҳатто бо беҳтарин муоҳимот, гузаштаги имконпазир аст. Муайянкунии зуда, калиди барқарорсозии система аст.</p>\n\n<h3>Муайяни занҷоширо интиқори фишори ҳоми</h3>\n<p>Афзудани тадриҷии фишор дар помпаи об бе тағйирот дар танзими шир, аввалин рамзҳои занҷоши рибаро намоён мекунад. Барои ҳалли ин мушкил, марҳилаҳои зеринро иҷро кунед:</p>\n<ol>\n<li><strong>Шустани обӣ:</strong> Суръати ҷараёнро муваққатан афзунед, то зарраҳои мавҷуда хориҷ шаванд.</li>\n<li><strong>Шустани кислотагӣ:</strong> Майи кислотагиро тавассути системаи инжекторӣ воред кунед. Ин амал олави кимиёвиро ҳал мекунад.</li>\n<li><strong>Шустани кальсий-хлоридӣ:</strong> Барои олавҳои кальсийӣ, шустани майи кальсий-хлорид самаранокист.</li>\n</ol>\n<p>Агар пас аз ин марҳилаҳо фишор бозгашт, нишон медорад, ки қатраҳо ғайриоддӣ нобуд шудаанд ва лангари тип ба иваз кардан ниёз дорад. Иваз кардани лангар дар миёнаи фасл хараҷнок аст, аммо агар решаҳо хушк шаванд, вайроншавии парвариш ҳанӯз бештар мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-موسیر-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری موسیر با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>нигоҳубини лангари тип парвариши ҳосил</figcaption></figure>\n\n<h3>Назорати воҳидии тақсимоти об</h3>\n<p>Барои боварӣ ҳосил кардан, ки ҳама қисмҳо об гирифтаанд, ҳар моҳ як боздиди диданӣ иҷро кунед. Обро аз охирини лангар ҷамъ кунед ва мушоҳида кунед, ки оқими об ором аст ё не. Кобирӣ дар охирини лангар нишон медиҳад, ки фишор дар тӯли хат паст шудааст, ки бояд тавассути танзими помпа ё иваз кардани лангар бо қутри калонтар ислоҳ карда шавад. Дар ин соҳа, таҳқиқот <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B3%D8%A8%D8%B2%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори тухм ва андоза дар як гектар</a> метавонад ба шумо кӯмак кунад, то фишори лозимаро бар асоси дарозии қатъҳои парварёна ҳисоб кунед. Фишори кофӣ барои расидан ба охирини қатъҳои дароз муҳим аст.</p>\n\n<h2>Фасли чорум: Паймони фасл ва тайёрӣ барои давраи оянда</h2>\n<p>Коси кишоварзон лангарҳои типро дар охири фасли парвариш мегузоранд. Ин кори нодуруст аст. Лангарҳои типи полиэтилении сифаташон хуб, агар дуруст нигоҳ дошта шаванд, барои истифода дар фасли оянда мувофиқанд.</p>\n\n<h3>Оператсияи халӣ кардан ва шустан</h3>\n<p>Пеш аз кундани парвариши навбатӣ, системаро пурра халӣ кунед. Иҷозат накунед, ки об дар банди (риштаи) обёрӣ монанд, зеро бӯмҳо (ҷинсҳои обӣ) дар рӯшноӣ ва оби бозистанда тавр муваққатӣ меафзоянд. Беҳтарин усул ин инъикоси маҳлуи пасткишкунанда (масалан, хлор бо дозаи баланд) дар давоми як соат аст. Сипас системаро бо оби тозашустанӣ барои хориҷ кардани моддаҳои кимиёвӣ шустанед. Ин марҳила имкон медиҳад, ки банд дар анбор то 20-30 соли оянда бе мушкилоти вазъ дорад.</p>\n\n<h3>Дархӯрднок будани (моддаҳои кимиёвӣ) дуруст</h3>\n<p>Риштаро дар атрофи ғиледро гардонед ва онҳоро дар ҷои соя ва дур аз равшанӣи мустақими офтоб гузоред. Равшани ултрабунафш (UV) душмани асосии полиэтилен аст. Ғилёророро уфуқӣ нигоҳ доред, то тағйироти таҷаҳузони банд дар давоми муҳлати дарозро тағйир надиҳад. Инчунин, илзоми риштаҳо бо маълумоти пайваста бо соли парвариш, ғафсӣ ва вазн, роҳи идоракунии анборро содда мекунад. Шумо метавонед дар бораи Ғилаккунии физикӣ банд маълумоти зиёдтарро дар дастуралии нигоҳдорӣ банд обёрӣ ва нуқтаҳои пайваста бо онҳо дидор мекунед.</p>\n\n<>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<p><strong>Саволи 1: Оё имкони истифода бурдани риштаи тиби сарсоқ барои сабзиёти дигар мавҷуд аст?</strong><br>Бале, аммо бо танзими масофаи қатраҳо. Сарсоқ одатан бо масофаи қатраҳои 10-12 сантиметр кор мекунад. Барои томатор ё қаламфул, ин масофа метавонад фарқ кунад. Нуқтаи муҳим, мутобиқ кардани суръати баромад бо ниёзоти растани аст.</p>\n\n<p><strong>Саволи 2: Ҳар чанд вақт бора филтарро тоза кардан лозим аст?</strong><br>Пешниҳод карда мешавад, ки ҳар ҳафта дар мавсими фаъоли кӯрпаҷурии гардишии фильтрҳо ба роҳ оварда, зарраҳои ҷомешударро партоед. Ин одати сода аз гирифти 90% қатраҳо пешгирӣ мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-موسیر-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری موسیر با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care сабзаҷӯ (mусӣ)</figcaption></figure>\n\n<p><strong>Саволи 3: Агар пашпашаҳои об дар навари қатравӣ зоҳир шаванд, чӣ кардан лозим аст?</strong><br>Пашпашаҳои об (Root Knot Nematodes) тавассути об ба реша ворид мешаванд. Истифодаи филтрҳои қаъқабии хеле майда ва инчунин шустан бо пергушӣ дар охири мавсим беҳтарин усули муқобила аст. Ғайр аз ин, боварӣ ҳосил кунед, ки манбаи оби шумо олуданашудааст.</p>\n\n<p><strong>Саволи 4: Фишори мувофиқи наварӣ барои сабзаҷӯ чадар аст?</strong><br>Одатан барои наварҳои стандарӣ байни 0.5 то 1 бар аст. Агар фишор боло равад, қатраҳо тезтари партобандӣ мебошанд ва обро аз реша дур меоранд. Истифодаи фишорнақс (manometer) дар шитоби асосӣ пешниҳод карда мешавад.</p>\n\n<p><strong>Саволи 5: Оё наварӣ ба ивазкунии солнаҳойӣ ниёз дорад?</strong><br>Не, агар аз намудҳои UV-Stabilized истифода кунед ва дар тӯли шаб пайваст бошед (на танҳо дар мавсими нақъ), умри муфоди онҳо 3 то 5 сол аст. Истифода дар чандин сабзаҷӯҳои пайдарпаӣ дар як замина беҳтарин усули иқтисоди аст.</p>\n\n<h2>Хулоса ва нуқтаҳои тилоӣ</h2>\n<p>Боварманд шудан дар кишт кардани шағол ва истифодаи системаи наққораи дароз (drip) ҳеҷ гоҳ раванди як маротибагӣ нест. <strong>Нигоҳубини наққораи дароз барои шағол</strong> Ин як даври доимӣ аз назорат, шустушу ва ислоҳоти ҷузъиӣ аст. Бо риояи чораҳои бехатарӣ барои филтрҳо, истифодаи шустушуи дурахмонӣ барои пешгирӣ аз тӯбкунӣ ва нақшагирии дақиқ барои шустушу ва захира дар охирси сол, шумо метавонед истифодаи обро то 40% нисбат ба обёрӣи земагинӣ кам кунед ва ҳамзамон сифати шағолро ба сатҳи тиҷоратӣ расонед. Фаромӯш накунед, ки боғзори, ки системаи обёрӣш солим аст, стресс камтар дорад ва аз ҷиҳати иқтисодӣ сарфаи бештар мекунад. ҳамеша ба ҷузъиёти хурдтарин ноқтаҳо диққат диҳед, зеро аҳамияти хоси онҳо ояндаи маҳсулотро муайян мекунад. Бо риоя ин дастурҳо ва истифодаи манбаъҳои ихтисосӣ дар веб, системаи обёрии худро ба сармояи дарозмуддат барои боғзоратон табдил диҳед.</p>\n<p><strong>Маводи вобаста:</strong> <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D9%BE%D9%84%D8%A7%DA%A9%D8%AF%D8%A7%D8%B1/">D986D988D8A7D8B1 D8AADB8CD9BE D8A2D8A8DB8CD8A7D8B1DB8C D9BED984D8A7DAA9D8AFD8A7D8B1</a>， <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%84%D9%88%D8%A8%DB%8C%D8%A7-%DA%86%DB%8C%D8%AA%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D984D988D8A8DB8CD8A7 DA86DB8CD8AADB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Нигоҳубinii noiri TEPi dar ғояри shaligʻ: Strategiyo amaliyotbari barои optimizatsiya rizod va soxhon','Коркардӣ шӯмпокқоли бе идоракунии дурусти намӣ хатари бузург дорад. Дар ин мақола мо тартиби мухлати кӯмакрасмонӣ-намдории махсуси шӯмпокқолиро аз насб то поёни фасл пурра баррасӣ мекунем, то шумо тавонад беҳтарин натиҷаҳоро доред.','publish','closed','closed','nigohubii-noiri-tepi-shalig',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
