INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррада: Чаро осеботи маъмурии қапиқӣ барои парвариши шоқоди чӯрӣ муҳим аст</h2>\n<p>Шоқоди чӯрӣ яке аз сабзавотҳои ҳассос ба намии хок аст, ки дар сурати идоракунии нодурусти осебот, заиф бар дастнишустани гӯрӯҳи васеи <strong>аз зараррасонҳо ва бемориҳои шоқоди чӯрӣ бо осеботи қапиқӣ</strong> шуда мешавад. Осеботи қапиқӣ, бо илтимоси дақиқи об ва кам кардани намии сатҳии хок, нақши асосиро дар пешгирии бемориҳои қозукӣ ва бактериявӣ мебозад. Дар ин баҳс ба таҳқиқи он чӣ тавр намуди системаи осебот ба паҳншавии зараррасонҳо ва бемориҳо таъсир мерасонад, ишора мекунем. Идоракунии дурусти манбаҳои об на танҳо хароҷотҳоро кам мекунад, балки саломатии гиёҳро дар муқобили омили беморсозҳо ҳимоя мекунад. Бо фаҳмиши амиқтари физикаи хок ва суръати ҷамъшавии об, деҳқонҳо метавонанд барномаро беҳтар созаданд. Ин роҳбарӣ инчунин ба мувофиқатӣ бо принсипҳои умумии заръкорӣ мисли <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B0%D8%B1%D8%AA-%D8%B9%D9%84%D9%88%D9%81%D9%87-%D8%A7%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">миқдори бодаи ҷӯи ғалла бар ҳектар</a> ҳушор мекунад, ки модели монандро барои идоракунии манбаҳо дар зиръи гуногун ба кор барданд. Оптимизатсияи истеъмолоти об дар марҳилаи истеҳсолот бевосита ба сифати ниҳоии қоҷ ва сари шоқоди чӯрӣ таъсир мерасонад. ҳадафи асосӣ ин аст, ки бо кам кардани нисбии муҳити сатҳӣ, шароити муносиб барои рушди беморсозҳоро нест кунем.</p>\n\n<h2>Таъсири осеботи қапиқӣ ба паҳншавии бемориҳои қозукӣ</h2>\n<p>Қозуҳо, мисли ҷинори рӯӣ ва зингарзанӣ, аз шумораи паҳншудаи <strong>Шӯрхорҳо ва бемориҳои марчубоб бо обёрӣи зарринӣ</strong> анд, ки дар шароити намии баланд фаъол мешаванд. Обёрӣи зарринӣ бо намнок нигоҳ доштани танҳо минтақаи реша ва хушк нигоҳ доштани таҷи ҷунҷоро зиноварии бемориро ба таври ғайриоддӣ кам мекунад. Дар муқоиса бо обёрӣи шаҳрисӣ ё боранӣ, нисбии намӣ дар атрофи баргҳо дар системаи зарринӣ хеле пасттар аст. Ин боиси кам шудани инсенсатсияи спорҳои занбоқорӣ (Inoculum) мегардад. Инчунин, фаҳмидани алоқа байни обёрӣ ва рушди ҷунҷор зарур аст; масалан, таҳқиқот <a href="https://navar-abyari.ir/melon-yield-per-hectare-guide/">Роҳнамун барои ҳосили зардӣ дар гектар</a> метавонад фаҳмиши шумо аз идоракунии намӣ дар сабзавоти дӯстдорандаи намро пуррӯягӣ кунад, гарчанде ки марчубоб ҳассосияти гуногун дорад. Назорати дақиқи намӣ, хати дифои аввал дар бархӯрди ин патоҷенҳо аст. Ин назорат бояд бо дақиқии баланд иҷро шавад, то дар ҳамин замин аз хушк шудани зиёди решаҳо низ пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-مارچوبه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های مارچوبه با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation марчубоб</figcaption></figure>\n\n\n<h3>Назорати хок ва пешгирӣ аз бемориҳои решагӣ</h3>\n<ul>\n<li>Истифодаи зарринҳои бо фишори мувофиқ барои дахоли об ба чуқурӣи кофӣ бе толиш кардани сатҳ.</li>\n<li>Бекор кардани даври системаи обёрӣ барои пешгирӣ аз ҷамъшавии нимвобарории зиёд дар қабатҳои поёнӣ.</li>\n<li>Истифодаи омехтаҳои органики мувофиқ, ки ба барқарорсозии микробиологияи хок мусоидат мекунанд.</li>\n</ul>\n\n<h2>Паҳлӯи зараррасонии ҳашарот тавассути идоракунии намнокӣ</h2>\n<p>Зараррасонҳои ҳашарот ба монанди мӯякӯдак ва ште (шипаш), дар муҳитҳои гарм ва намнок зудтар такрор мешаванд. Бо кам кардани намнокии муҳит тавассути <strong>Зараррасонҳо ва бемориҳои шпинат (марчуба) бо ороёбии қатрагӣ (дамлаб)</strong> шумораи ин ҳашарот кам мешавад. Штеҳо барои ҷифтигирӣ ва тухмҳамовӣ ба шароити муносибтар дар экосистема ниёз доранд, ки дар ҳавои хушк камтар муайян мешавад. Инчунин, камои намнокӣ боиси он мегардад, ки баъзе паноҳгоҳҳо (гнездаҳо) барои зараррасонҳо камтар давомнокият доранд. Барои дарки беҳтари тағйирёбандаҳои кишоварзӣ, шумо метавонед <a href="https://navar-abyari.ir/dill-seed-per-hectare-factors-increase-yield/">омилҳое, ки ба зиёд кардани ҳосили бӯкӣ-сабзиш (شنبелиله) дар як гектар мусоидат мекунанд</a> ро омӯзед, то бидед, ки чӣ тавр тағйироти кишоварзӣ ба саломатию афғонии растани таъсир мерасонад. Пайдо кардани мониторинги доимӣ калиди муваффақият дар ин марҳила аст. Байни намнокии хок ва ҷалби зараррасонҳо робитаи мустақим вуҷуд дорад, ки бояд дида шуда бошад. Бо кам шудани намнокӣ, фаъолияти метаболикӣ-и бисёр паразитҳои хокзамдон низ кам мешавад, ки ин ба бемонандии бештари растани мусоидат мекунад. Ин механизмҳои табиӣ яке аз муҳимтарин фоидаҳои системаҳои ороёбии дақиқ ҳисоб карда мешавад.</p>\n\n<h3>Мониторинги зеҳникор ва шинохти муқаддам</h3>\n<ol>\n<li>Зафтиши ҳафтаноми сатҳи баргҳо барои муайян кардани догҳои зард ё қаҳваранг.</li>\n<li>Санҷишни минтақаи решаҳо барои аломатҳои сиёҳшавӣ ва бӯи пӯсида.</li>\n<li>Истифодаи зарпӯшиҳои зард барои назорати популятсияи ҳашорот парранда.</li>\n</ol>\n\n<h2>Нақши системаҳои нафари тайп ва чангӯлӣ дар пешгирӣ</h2>\n<p>Нафари тайп доимӣ яке аз самараноктарин усулҳои оборӣ барои сабзавотҳои сафтаравӣ, ба монанди шӯмешок мебошад. Ин система обро ба таври якхела дар тӯли нафар тақсим мекунад ва аз ҷамъшавии об дар нуқтаҳои мушаххас пешгирӣ мекунад. Истифодаи нафари тайп доимӣ метавонад имконияت доҳад, ки решаҳо дар шартҳои идеалӣ руянд ва тобоварии наботот бар зидди стресси беморииро зиёд намояд. Инчунин, агар ба идоракунии парранҷамеҳии арзқон таваҷҷуҳ дошта бошед, омӯзиш <a href="https://navar-abyari.ir/mixed-crop-yield-per-hectare-iraq/">фаъолияти парранҷамеҳӣ дар һактари Ироқ</a> метавонад фикрҳое барои илова кардани давраи ҳашорот ва кам кардани вобастагӣ ба парешоккунӣи кимиёвӣ пешниҳод кунад. Ин усули ягона, калиди идоракунии устувор аст. Интихоби дурусти қисмҳои системаи оборӣ ба устувории тамоми давраи истеҳсолот таъсир мерасонад. Инчунин, таваҷҷуҳ ба ҷузъиёти насби ламбҳо ва фосилаи чангӯлҳо аз кабудакҳо аз пуфидани кабудакҳо дар ҷои пайвастшавӣ бо об пешгирӣ мекунад. Ин пешгирии физикӣ хеле арзонтар ва бехатартар аз табобати кимиёвӣ пас аз пайдо шудани беморӣ мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-مارچوبه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های مارچوبه با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation шӯмешок</figcaption></figure>\n\n\n<h2>Тавсияҳои амалӣ барои деҳқонон</h2>\n<p>Барои ба даст овардани ҳосили афзун <strong>Ағдаргӣ ва бемориҳои шпинат бо обёрӣи чуқуқӣ</strong>риояти тавсияҳои зерин лозим аст. Аввалан, фишори обро тавре танзим кунед, ки хок ноҳид намешавад ва танҳо дар радиуси 30 то 50 сантиметр ба наздикии раста дучор мешавад. Дуввумин, аз оби хунук ва камнамк истифода барадед, то шоки физиологӣи раста пешгирӣ гардад. Савум, агар аломатҳои беморӣ мушоҳида шуда, обёрӣро муваққатан қат кунед ва аз ҳашараткунандаҳои биологӣ истифода баред. Дар бораи бӯдаву дунгу дурӯғ, принсипҳои монанд мавҷуданд; масалан, <a href="https://navar-abyari.ir/barley-yield-per-hectare-guide/">Роҳнамоии ҳосили шӯр дар ҳектар</a> нишон медиҳад, ки идоракунии намнокӣ пешшоҳиди ҳар гуна муваффақият дар кишворубӣ аст. Илова бар ин, баръи сабзи дигар ба монанди бодиринг (бадомҷини), дониши миқдори дучу усули кишт ғайри оддӣ муҳим аст, ки дар <a href="https://navar-abyari.ir/eggplant-seed-quantity-per-hectare-planting-irrigation-tips/">Тавсияҳои кишт ва обёрӣ барои бадминг</a> шарҳ дода шудааст. Ин муқоисаҳо ба деҳқон кӯмак мерасонанд, ки заминаро барои рушди солимтар омода кунанд. Такрор ин равандҳоро бо дақиққ, фарқият байни ҳосили зарардида ва ҳосили солом ва боарҳро муайян мекунад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<p>1. Оё ороишӣ бо қатравуни (drip) метавонад аз паҳн шудани занбулҳои хокӣ пешгирӣ кунад?<br>Бале, зеро сатҳи хок хушк мемонад ва занбулҳо барои ҳаракат ба рағбат лозим доранд.<br>2. Вақте бояд ороишгириҳоро иваз кунед?<br>Ҳар сол ё агар хӯра кунед, барои нигоҳ доштани фишори якхела.<br>3. Оё метавон аз нӯри типи барои лавҳа иваз кард?<br>Бале, нӯри типи устувор хеле мувофиқ аст, зеро рағбатро дақиқтар идора мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-مارچوبه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های مارچوبه با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation марчубе</figcaption></figure>\n\n\n<h2>Хулоса</h2>\n<p>Мудирият <strong>Беморӣ ва зарарангоронии спаржа бо озири тамчилӣ</strong> Ин як роҳи пешгирикунӣ ва пастидоркунанда аст, ки ба кам кардани истифодаи зарарангорҳои кимиёвӣ кӯмак мекунад. Бо диққат ба назорати намӣ, пайдои бемам ва интихоби дурусти системаи озири (тачилӣ ё навори чип), сифат ва ҳаҷми меҳвари спаржа-ро ба таври ошкор зиёд кардан мумкин аст. Кишоварони ҳақиқӣ ва тиҷоратӣ бояд ин аслҳоро дар нақшаи сораи худ ҷойгир намоянд, то таълуфатҳо аз сабаби омилҳои биологӣ ба ҳадди ақал расонида шаванд. Истифодаи маълумоти илмӣ ва таҷрибӣ сармоягузории ҷонбағир барои ояндаи санъати сабзавот аст. Намоишҳои дар кӯл ва ободии озирашавии зеҳнӣ барои барориши зараро ба молиҳо таъсири дорад, ки ин технологияҳо ҷуда шудаанд ва кишоварони оянданок тавассути сармоягузорӣ дар онҳо, аз таълифатҳои бозор ва зарари бемориҳо муҳифзат шаванд. Ин роҳи умумӣ таъмини истеҳсоли пастидоркунанда дар муҳлати дароз аст.</p>','Идоракунии зараррасонҳо ва бемориҳои шпинат дар системаи обёрӣ анорӣ: Раҳнамои амалӣ','Чӣ тавр бо истифода аз абории чуққатӣ паҳншавии зараррасонҳо ва бемориҳои камарҳоро танзим карда, ҳудуди тарроҳӣ ва пӯсишро кам ва сифати меҳварро афзун кунем? Дар ин мақолаи ихтисосӣ чораҳои асосӣ оварда шудааст.','publish','closed','closed','idorakuniji-zararrasonho-shpinat-sistemi-obori-anori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
