SET @translation_id=(SELECT post_id FROM `ha_postmeta` WHERE meta_key='_navar_translation_queue_key' AND meta_value='article-translation:crop-296:en-US' LIMIT 1);
SET @slug_conflict=(SELECT ID FROM `ha_posts` WHERE post_name='asparagus-pest-disease-management-drip-irrigation-practical-guide' AND post_type='post' AND (@translation_id IS NULL OR ID<>@translation_id) LIMIT 1);
SET @translation_id=COALESCE(@translation_id,IF(@source_post_id IS NOT NULL AND @slug_conflict IS NULL,LAST_INSERT_ID(),NULL));
COMMIT;

